from fastapi import FastAPI, Body
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/strict")
async def strict_json(data: dict = Body(..., strict_content_type=True)):
    return data

@app.post("/non-strict")
async def non_strict_json(data: dict = Body(..., strict_content_type=False)):
    return data

client = TestClient(app)

def test_strict_json_correct_content_type():
    response = client.post("/strict", json={"foo": "bar"}, headers={"Content-Type": "application/json"})
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

def test_strict_json_wrong_content_type():
    # This should fail because strict_content_type=True and Content-Type is not application/json
    response = client.post("/strict", json={"foo": "bar"}, headers={"Content-Type": "application/ld+json"})
    assert response.status_code == 422

def test_strict_json_missing_content_type():
    # This should fail because strict_content_type=True and Content-Type is missing
    response = client.post("/strict", json={"foo": "bar"}, headers={})
    assert response.status_code == 422

def test_non_strict_json_correct_content_type():
    response = client.post("/non-strict", json={"foo": "bar"}, headers={"Content-Type": "application/json"})
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

def test_non_strict_json_wrong_content_type():
    # This should succeed because strict_content_type=False and application/ld+json is allowed
    response = client.post("/non-strict", json={"foo": "bar"}, headers={"Content-Type": "application/ld+json"})
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

def test_non_strict_json_missing_content_type():
    # This should succeed because strict_content_type=False and missing Content-Type is allowed
    response = client.post("/non-strict", json={"foo": "bar"}, headers={})
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

if __name__ == "__main__":
    pytest.main([__file__])

